import React from "react";
import './ProductHome.css'
const products = {
  "PC Components": [
    {
      name: "Graphics Card",
      img: "https://cdn.pixabay.com/photo/2016/11/29/03/53/pc-1867755_1280.jpg",
    },
    {
      name: "Motherboard",
      img: "https://cdn.pixabay.com/photo/2016/11/19/14/00/pc-1836107_1280.jpg",
    },
    {
      name: "RAM",
      img: "https://cdn.pixabay.com/photo/2014/05/02/21/50/computer-336475_1280.jpg",
    },
  ],
  "Laptop Components": [
    {
      name: "Laptop Battery",
      img: "https://cdn.pixabay.com/photo/2016/11/29/04/17/laptop-1867745_1280.jpg",
    },
    {
      name: "Laptop Charger",
      img: "https://cdn.pixabay.com/photo/2016/03/27/22/16/technology-1283624_1280.jpg",
    },
    {
      name: "Laptop SSD",
      img: "https://cdn.pixabay.com/photo/2015/01/08/18/24/laptop-593673_1280.jpg",
    },
  ],
  "Mobile Components": [
    {
      name: "Phone Display",
      img: "https://cdn.pixabay.com/photo/2014/09/23/21/23/smartphone-458856_1280.jpg",
    },
    {
      name: "Phone Battery",
      img: "https://cdn.pixabay.com/photo/2013/07/12/12/58/smartphone-146721_1280.png",
    },
    {
      name: "Phone Camera Module",
      img: "https://cdn.pixabay.com/photo/2015/07/17/22/43/student-849821_1280.jpg",
    },
  ],
  "Cloth Components": [
    {
      name: "T-Shirt",
      img: "https://cdn.pixabay.com/photo/2016/03/27/19/31/fashion-1283863_1280.jpg",
    },
    {
      name: "Jeans",
      img: "https://cdn.pixabay.com/photo/2015/09/02/12/45/fashion-918446_1280.jpg",
    },
    {
      name: "Hoodie",
      img: "https://cdn.pixabay.com/photo/2015/03/26/09/41/fashion-690546_1280.jpg",
    },
  ],
};

const ProductHome = () => {
  return (
    <div className="p-6">
      <h1 className="text-3xl font-bold mb-6 text-center">Explore Categories</h1>
      {Object.entries(products).map(([category, items]) => (
        <div key={category} className="mb-10">
          <h2 className="text-2xl font-semibold mb-4">{category}</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
            {items.map((item, index) => (
              <div key={index} className="bg-white rounded-xl shadow-md p-4 hover:shadow-lg transition duration-300">
                <img
                  src={item.img}
                  alt={item.name}
                  className="h-48 w-full object-cover rounded-md mb-2"
                />
                <h3 className="text-lg font-medium text-gray-700 text-center">{item.name}</h3>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

export default ProductHome;
